-- ============================================================================
-- MemberJunction PostgreSQL Migration — V202611231029__v6.3.x__Communications_V2_Schema.sql
-- Split-and-regenerate with INLINE NATIVE CodeGen baking: hand-written DDL transpiled
-- (AST dialect), metadata DML inline, and CodeGen objects (views/sprocs/triggers/grants)
-- baked natively from `mj codegen`. Applies standalone via `mj migrate` — no deploy codegen.
-- ============================================================================

CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE SCHEMA IF NOT EXISTS __mj;
SET search_path TO __mj, public;
SET standard_conforming_strings = on;

/* ============================================================================ */
/* Communications V2 — principals, senders, endpoints, preferences, suppression, */
/* activity and metadata-driven compliance (regimes + jurisdictions) */
/* ============================================================================ */
/* Design: "MJ Comms V2 — Design Plan: Principals, Preferences & Compliance" */
/* Additive only: */
/*   * 20 new tables (2 generic: Jurisdiction, JurisdictionMember; */
/*     plus CommunicationProviderEvent and CommunicationSendingDomain) */
/*   * new columns on EntityCommunicationMessageType, CommunicationLog, */
/*     and CommunicationProvider */
/*   * CHECK / UNIQUE constraints, non-FK supporting indexes, descriptions */
/* CodeGen owns: __mj_CreatedAt/__mj_UpdatedAt, FK indexes, views, procedures, */
/* EntityField rows, value lists (from the CHECK constraints) and generated classes. */
/* Shipped separately as /metadata JSON (NOT in this migration): */
/*   * polymorphic FK decorations (EntityIDFieldName) — see */
/*     metadata/entities/.polymorphic-fk-entity-fields.json additions in the plan */
/*   * seed rows: the default "Company" sender type over MJ: Companies, MJ: Users */
/*     as a built-in principal, jurisdictions (countries, EU/EEA groups), rule */
/*     types and starter regimes */
/* NULL-scope uniqueness: SQL Server UNIQUE constraints treat NULLs as equal, which */
/* is the intended semantics here (one "all senders" row per scope). The release */
/* build's PostgreSQL conversion must emit NULLS NOT DISTINCT for those constraints. */
/* PostgreSQL counterpart is produced by the release build. */
/* ============================================================================ */
/* =========================================================================== */
/* 1. JURISDICTIONS (generic core — usable beyond communications) */
/* =========================================================================== */
CREATE TABLE __mj."Jurisdiction" (
  "ID" UUID NOT NULL DEFAULT GEN_RANDOM_UUID(),
  "Code" VARCHAR(20) NOT NULL,
  "Name" VARCHAR(200) NOT NULL,
  "Description" TEXT NULL,
  "Type" VARCHAR(20) NOT NULL,
  "CountryID" UUID NULL,
  "Status" VARCHAR(20) NOT NULL DEFAULT 'Active',
  CONSTRAINT "PK_Jurisdiction" PRIMARY KEY ("ID"),
  CONSTRAINT "UQ_Jurisdiction_Code" UNIQUE NULLS NOT DISTINCT (
    "Code"
  ),
  CONSTRAINT "FK_Jurisdiction_Country" FOREIGN KEY ("CountryID") REFERENCES __mj."Country" (
    "ID"
  ),
  CONSTRAINT "CK_Jurisdiction_Type" CHECK ("Type" IN ('Country', 'Subdivision', 'Group')),
  CONSTRAINT "CK_Jurisdiction_Status" CHECK ("Status" IN ('Active', 'Disabled'))
);

CREATE TABLE __mj."JurisdictionMember" (
  "ID" UUID NOT NULL DEFAULT GEN_RANDOM_UUID(),
  "GroupJurisdictionID" UUID NOT NULL,
  "MemberJurisdictionID" UUID NOT NULL,
  CONSTRAINT "PK_JurisdictionMember" PRIMARY KEY ("ID"),
  CONSTRAINT "UQ_JurisdictionMember_Pair" UNIQUE NULLS NOT DISTINCT (
    "GroupJurisdictionID",
    "MemberJurisdictionID"
  ),
  CONSTRAINT "FK_JurisdictionMember_Group" FOREIGN KEY ("GroupJurisdictionID") REFERENCES __mj."Jurisdiction" (
    "ID"
  ),
  CONSTRAINT "FK_JurisdictionMember_Member" FOREIGN KEY ("MemberJurisdictionID") REFERENCES __mj."Jurisdiction" (
    "ID"
  ),
  CONSTRAINT "CK_JurisdictionMember_NotSelf" CHECK ("GroupJurisdictionID" <> "MemberJurisdictionID")
);

/* =========================================================================== */
/* 2. PRINCIPALS (who we communicate with) */
/* =========================================================================== */
CREATE TABLE __mj."CommunicationPrincipal" (
  "ID" UUID NOT NULL DEFAULT GEN_RANDOM_UUID(),
  "EntityID" UUID NOT NULL,
  "Name" VARCHAR(100) NOT NULL,
  "Description" TEXT NULL,
  "DriverClass" VARCHAR(200) NULL,
  "Configuration" TEXT NULL,
  "DisplayOrder" INT NOT NULL DEFAULT 0,
  "Status" VARCHAR(20) NOT NULL DEFAULT 'Active',
  CONSTRAINT "PK_CommunicationPrincipal" PRIMARY KEY ("ID"),
  CONSTRAINT "UQ_CommunicationPrincipal_EntityID" UNIQUE NULLS NOT DISTINCT (
    "EntityID"
  ),
  CONSTRAINT "UQ_CommunicationPrincipal_Name" UNIQUE NULLS NOT DISTINCT (
    "Name"
  ),
  CONSTRAINT "FK_CommunicationPrincipal_Entity" FOREIGN KEY ("EntityID") REFERENCES __mj."Entity" (
    "ID"
  ),
  CONSTRAINT "CK_CommunicationPrincipal_Status" CHECK ("Status" IN ('Active', 'Disabled'))
);

ALTER TABLE __mj."EntityCommunicationMessageType"
  ADD COLUMN "CommunicationPrincipalID" UUID NULL CONSTRAINT "FK_EntityCommunicationMessageType_CommunicationPrincipal" REFERENCES __mj."CommunicationPrincipal" (
    "ID"
  );

/* =========================================================================== */
/* 3. SENDERS (who is communicating: company, brand, tenant, newsletter, ...) */
/* =========================================================================== */
CREATE TABLE __mj."CommunicationSenderType" (
  "ID" UUID NOT NULL DEFAULT GEN_RANDOM_UUID(),
  "Name" VARCHAR(100) NOT NULL,
  "Description" TEXT NULL,
  "EntityID" UUID NULL,
  "DriverClass" VARCHAR(200) NULL,
  "Configuration" TEXT NULL,
  "Status" VARCHAR(20) NOT NULL DEFAULT 'Active',
  CONSTRAINT "PK_CommunicationSenderType" PRIMARY KEY ("ID"),
  CONSTRAINT "UQ_CommunicationSenderType_Name" UNIQUE NULLS NOT DISTINCT (
    "Name"
  ),
  CONSTRAINT "FK_CommunicationSenderType_Entity" FOREIGN KEY ("EntityID") REFERENCES __mj."Entity" (
    "ID"
  ),
  CONSTRAINT "CK_CommunicationSenderType_Status" CHECK ("Status" IN ('Active', 'Disabled'))
);

CREATE TABLE __mj."CommunicationSender" (
  "ID" UUID NOT NULL DEFAULT GEN_RANDOM_UUID(),
  "CommunicationSenderTypeID" UUID NOT NULL,
  "RecordID" VARCHAR(450) NULL,
  "ParentSenderID" UUID NULL,
  "Name" VARCHAR(200) NOT NULL,
  "Description" TEXT NULL,
  "IsDefault" BOOLEAN NOT NULL DEFAULT FALSE,
  "FromEmail" VARCHAR(320) NULL,
  "FromName" VARCHAR(200) NULL,
  "ReplyToEmail" VARCHAR(320) NULL,
  "FromPhone" VARCHAR(32) NULL,
  "SendingDomain" VARCHAR(255) NULL,
  "PostalAddress" VARCHAR(1000) NULL,
  "JurisdictionID" UUID NULL,
  "CommunicationProviderID" UUID NULL,
  "CredentialID" UUID NULL,
  "PreferenceCenterURL" VARCHAR(1000) NULL,
  "TemplateContext" TEXT NULL,
  "Configuration" TEXT NULL,
  "EnforcementMode" VARCHAR(10) NULL,
  "DeliveryGuarantee" VARCHAR(20) NULL,
  "Status" VARCHAR(20) NOT NULL DEFAULT 'Active',
  CONSTRAINT "PK_CommunicationSender" PRIMARY KEY ("ID"),
  CONSTRAINT "FK_CommunicationSender_SenderType" FOREIGN KEY ("CommunicationSenderTypeID") REFERENCES __mj."CommunicationSenderType" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationSender_ParentSender" FOREIGN KEY ("ParentSenderID") REFERENCES __mj."CommunicationSender" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationSender_Jurisdiction" FOREIGN KEY ("JurisdictionID") REFERENCES __mj."Jurisdiction" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationSender_Provider" FOREIGN KEY ("CommunicationProviderID") REFERENCES __mj."CommunicationProvider" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationSender_Credential" FOREIGN KEY ("CredentialID") REFERENCES __mj."Credential" (
    "ID"
  ),
  CONSTRAINT "CK_CommunicationSender_NotOwnParent" CHECK ("ParentSenderID" IS NULL OR "ParentSenderID" <> "ID"),
  CONSTRAINT "CK_CommunicationSender_EnforcementMode" CHECK ("EnforcementMode" IS NULL OR "EnforcementMode" IN ('Off', 'Shadow', 'Enforce')),
  CONSTRAINT "CK_CommunicationSender_DeliveryGuarantee" CHECK ("DeliveryGuarantee" IS NULL
  OR "DeliveryGuarantee" IN ('At Most Once', 'At Least Once')),
  CONSTRAINT "CK_CommunicationSender_Status" CHECK ("Status" IN ('Active', 'Suspended', 'Disabled'))
);

/* One sender per backing record of a type. Senders with no backing record (RecordID NULL) are unrestricted. */
CREATE UNIQUE INDEX "UX_CommunicationSender_TypeRecord" ON __mj."CommunicationSender"("CommunicationSenderTypeID", "RecordID") NULLS NOT DISTINCT
WHERE
  NOT "RecordID" IS NULL;

/* At most one default sender per instance (used when a send names no sender). */
CREATE UNIQUE INDEX "UX_CommunicationSender_IsDefault" ON __mj."CommunicationSender"("IsDefault") NULLS NOT DISTINCT
WHERE
  "IsDefault" = TRUE;

CREATE TABLE __mj."CommunicationSenderPermission" (
  "ID" UUID NOT NULL DEFAULT GEN_RANDOM_UUID(),
  "CommunicationSenderID" UUID NOT NULL,
  "RoleID" UUID NULL,
  "UserID" UUID NULL,
  "PermissionLevel" VARCHAR(20) NOT NULL,
  "AppliesToChildSenders" BOOLEAN NOT NULL DEFAULT TRUE,
  CONSTRAINT "PK_CommunicationSenderPermission" PRIMARY KEY ("ID"),
  CONSTRAINT "UQ_CommunicationSenderPermission_Grantee" UNIQUE NULLS NOT DISTINCT (
    "CommunicationSenderID",
    "RoleID",
    "UserID"
  ),
  CONSTRAINT "FK_CommunicationSenderPermission_Sender" FOREIGN KEY ("CommunicationSenderID") REFERENCES __mj."CommunicationSender" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationSenderPermission_Role" FOREIGN KEY ("RoleID") REFERENCES __mj."Role" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationSenderPermission_User" FOREIGN KEY ("UserID") REFERENCES __mj."User" (
    "ID"
  ),
  CONSTRAINT "CK_CommunicationSenderPermission_OneGrantee" CHECK ((
    "RoleID" IS NULL AND NOT "UserID" IS NULL
  )
  OR (
    NOT "RoleID" IS NULL AND "UserID" IS NULL
  )),
  CONSTRAINT "CK_CommunicationSenderPermission_Level" CHECK ("PermissionLevel" IN ('View', 'Send', 'Manage'))
);

/* =========================================================================== */
/* 4. ENDPOINTS (where we reach a principal; shared across principals) */
/* =========================================================================== */
CREATE TABLE __mj."CommunicationEndpoint" (
  "ID" UUID NOT NULL DEFAULT GEN_RANDOM_UUID(),
  "BaseMessageTypeID" UUID NOT NULL,
  "NormalizedValue" VARCHAR(320) NULL,
  "ValueHash" VARCHAR(64) NOT NULL,
  "Domain" VARCHAR(255) NULL,
  "Status" VARCHAR(20) NOT NULL DEFAULT 'Active',
  "SoftBounceCount" INT NOT NULL DEFAULT 0,
  "LastSentAt" TIMESTAMPTZ NULL,
  "LastDeliveredAt" TIMESTAMPTZ NULL,
  "LastBouncedAt" TIMESTAMPTZ NULL,
  "LastEngagedAt" TIMESTAMPTZ NULL,
  CONSTRAINT "PK_CommunicationEndpoint" PRIMARY KEY ("ID"),
  CONSTRAINT "UQ_CommunicationEndpoint_ValueHash" UNIQUE NULLS NOT DISTINCT (
    "BaseMessageTypeID",
    "ValueHash"
  ),
  CONSTRAINT "FK_CommunicationEndpoint_BaseMessageType" FOREIGN KEY ("BaseMessageTypeID") REFERENCES __mj."CommunicationBaseMessageType" (
    "ID"
  ),
  CONSTRAINT "CK_CommunicationEndpoint_SoftBounceCount" CHECK ("SoftBounceCount" >= 0),
  CONSTRAINT "CK_CommunicationEndpoint_Status" CHECK ("Status" IN ('Active', 'Soft Bouncing', 'Hard Bounced', 'Complained', 'Invalid', 'Erased')),
  CONSTRAINT "CK_CommunicationEndpoint_Erased" CHECK ((
    "Status" = 'Erased' AND "NormalizedValue" IS NULL
  )
  OR (
    "Status" <> 'Erased' AND NOT "NormalizedValue" IS NULL
  ))
);

/* Domain-level deliverability reporting (bounce and complaint rates by domain). */
CREATE INDEX "IX_CommunicationEndpoint_Domain" ON __mj."CommunicationEndpoint"("Domain", "Status");

CREATE TABLE __mj."CommunicationEndpointPrincipal" (
  "ID" UUID NOT NULL DEFAULT GEN_RANDOM_UUID(),
  "CommunicationEndpointID" UUID NOT NULL,
  "EntityID" UUID NOT NULL,
  "RecordID" VARCHAR(450) NOT NULL,
  "FirstSeenAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  "LastSeenAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT "PK_CommunicationEndpointPrincipal" PRIMARY KEY ("ID"),
  CONSTRAINT "UQ_CommunicationEndpointPrincipal_Link" UNIQUE NULLS NOT DISTINCT (
    "CommunicationEndpointID",
    "EntityID",
    "RecordID"
  ),
  CONSTRAINT "FK_CommunicationEndpointPrincipal_Endpoint" FOREIGN KEY ("CommunicationEndpointID") REFERENCES __mj."CommunicationEndpoint" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationEndpointPrincipal_Entity" FOREIGN KEY ("EntityID") REFERENCES __mj."Entity" (
    "ID"
  )
);

/* Reverse lookup: all endpoints of one principal record. */
CREATE INDEX "IX_CommunicationEndpointPrincipal_Principal" ON __mj."CommunicationEndpointPrincipal"("EntityID", "RecordID");

/* =========================================================================== */
/* 5. PREFERENCES */
/* =========================================================================== */
CREATE TABLE __mj."CommunicationPreference" (
  "ID" UUID NOT NULL DEFAULT GEN_RANDOM_UUID(),
  "CommunicationSenderID" UUID NULL,
  "Name" VARCHAR(200) NOT NULL,
  "Description" TEXT NULL,
  "Category" VARCHAR(100) NULL,
  "MessageClass" VARCHAR(20) NOT NULL DEFAULT 'Marketing',
  "DefaultState" VARCHAR(20) NOT NULL DEFAULT 'Opted In',
  "BaseMessageTypeID" UUID NULL,
  "IsUserVisible" BOOLEAN NOT NULL DEFAULT TRUE,
  "DisplayOrder" INT NOT NULL DEFAULT 0,
  "Status" VARCHAR(20) NOT NULL DEFAULT 'Active',
  CONSTRAINT "PK_CommunicationPreference" PRIMARY KEY ("ID"),
  CONSTRAINT "UQ_CommunicationPreference_SenderName" UNIQUE NULLS NOT DISTINCT (
    "CommunicationSenderID",
    "Name"
  ),
  CONSTRAINT "FK_CommunicationPreference_Sender" FOREIGN KEY ("CommunicationSenderID") REFERENCES __mj."CommunicationSender" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationPreference_BaseMessageType" FOREIGN KEY ("BaseMessageTypeID") REFERENCES __mj."CommunicationBaseMessageType" (
    "ID"
  ),
  CONSTRAINT "CK_CommunicationPreference_MessageClass" CHECK ("MessageClass" IN ('Transactional', 'Operational', 'Marketing')),
  CONSTRAINT "CK_CommunicationPreference_DefaultState" CHECK ("DefaultState" IN ('Opted In', 'Opted Out')),
  CONSTRAINT "CK_CommunicationPreference_Status" CHECK ("Status" IN ('Active', 'Disabled'))
);

CREATE TABLE __mj."CommunicationPrincipalPreference" (
  "ID" UUID NOT NULL DEFAULT GEN_RANDOM_UUID(),
  "EntityID" UUID NOT NULL,
  "RecordID" VARCHAR(450) NOT NULL,
  "CommunicationPreferenceID" UUID NOT NULL,
  "CommunicationSenderID" UUID NULL,
  "State" VARCHAR(20) NOT NULL,
  "OptInMethod" VARCHAR(20) NULL,
  "ConfirmedAt" TIMESTAMPTZ NULL,
  "ConfirmationToken" UUID NULL,
  "ConsentSource" VARCHAR(30) NOT NULL,
  "ConsentAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  "ConsentText" TEXT NULL,
  "ExpiresAt" TIMESTAMPTZ NULL,
  "CommunicationLogID" UUID NULL,
  "IPAddress" VARCHAR(45) NULL,
  "UserAgent" VARCHAR(1000) NULL,
  "ChangedByUserID" UUID NULL,
  CONSTRAINT "PK_CommunicationPrincipalPreference" PRIMARY KEY ("ID"),
  CONSTRAINT "UQ_CommunicationPrincipalPreference_Scope" UNIQUE NULLS NOT DISTINCT (
    "EntityID",
    "RecordID",
    "CommunicationPreferenceID",
    "CommunicationSenderID"
  ),
  CONSTRAINT "FK_CommunicationPrincipalPreference_Entity" FOREIGN KEY ("EntityID") REFERENCES __mj."Entity" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationPrincipalPreference_Preference" FOREIGN KEY ("CommunicationPreferenceID") REFERENCES __mj."CommunicationPreference" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationPrincipalPreference_Sender" FOREIGN KEY ("CommunicationSenderID") REFERENCES __mj."CommunicationSender" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationPrincipalPreference_Log" FOREIGN KEY ("CommunicationLogID") REFERENCES __mj."CommunicationLog" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationPrincipalPreference_ChangedByUser" FOREIGN KEY ("ChangedByUserID") REFERENCES __mj."User" (
    "ID"
  ),
  CONSTRAINT "CK_CommunicationPrincipalPreference_State" CHECK ("State" IN ('Pending', 'Opted In', 'Opted Out')),
  CONSTRAINT "CK_CommunicationPrincipalPreference_Pending" CHECK ("State" <> 'Pending' OR (
    "OptInMethod" = 'Double' AND "ConfirmedAt" IS NULL
  )),
  CONSTRAINT "CK_CommunicationPrincipalPreference_OptInMethod" CHECK ("OptInMethod" IS NULL OR "OptInMethod" IN ('Single', 'Double')),
  CONSTRAINT "CK_CommunicationPrincipalPreference_ConsentSource" CHECK ("ConsentSource" IN (
    'One-Click Header',
    'Preference Center',
    'Signup Form',
    'Provider Webhook',
    'Admin',
    'API',
    'Import'
  ))
);

CREATE UNIQUE INDEX "UX_CommunicationPrincipalPreference_ConfirmationToken" ON __mj."CommunicationPrincipalPreference"("ConfirmationToken") NULLS NOT DISTINCT
WHERE
  NOT "ConfirmationToken" IS NULL;

/* =========================================================================== */
/* 6. SUPPRESSION (hard blocks; many rows per principal / endpoint) */
/* =========================================================================== */
CREATE TABLE __mj."CommunicationSuppressionPolicy" (
  "ID" UUID NOT NULL DEFAULT GEN_RANDOM_UUID(),
  "Name" VARCHAR(200) NOT NULL,
  "Description" TEXT NULL,
  "DriverClass" VARCHAR(200) NOT NULL,
  "Parameters" TEXT NULL,
  "Status" VARCHAR(20) NOT NULL DEFAULT 'Active',
  CONSTRAINT "PK_CommunicationSuppressionPolicy" PRIMARY KEY ("ID"),
  CONSTRAINT "UQ_CommunicationSuppressionPolicy_Name" UNIQUE NULLS NOT DISTINCT (
    "Name"
  ),
  CONSTRAINT "CK_CommunicationSuppressionPolicy_Status" CHECK ("Status" IN ('Active', 'Disabled'))
);

CREATE TABLE __mj."CommunicationSuppression" (
  "ID" UUID NOT NULL DEFAULT GEN_RANDOM_UUID(),
  "CommunicationEndpointID" UUID NULL,
  "EntityID" UUID NULL,
  "RecordID" VARCHAR(450) NULL,
  "CommunicationSenderID" UUID NULL,
  "CommunicationPreferenceID" UUID NULL,
  "BaseMessageTypeID" UUID NULL,
  "Reason" VARCHAR(30) NOT NULL,
  "Source" VARCHAR(30) NOT NULL,
  "Status" VARCHAR(20) NOT NULL DEFAULT 'Active',
  "EffectiveAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  "ExpiresAt" TIMESTAMPTZ NULL,
  "RevokedAt" TIMESTAMPTZ NULL,
  "RevokedByUserID" UUID NULL,
  "CommunicationLogID" UUID NULL,
  "CommunicationSuppressionPolicyID" UUID NULL,
  "IPAddress" VARCHAR(45) NULL,
  "UserAgent" VARCHAR(1000) NULL,
  "Notes" TEXT NULL,
  "CreatedByUserID" UUID NULL,
  CONSTRAINT "PK_CommunicationSuppression" PRIMARY KEY ("ID"),
  CONSTRAINT "FK_CommunicationSuppression_Endpoint" FOREIGN KEY ("CommunicationEndpointID") REFERENCES __mj."CommunicationEndpoint" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationSuppression_Entity" FOREIGN KEY ("EntityID") REFERENCES __mj."Entity" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationSuppression_Sender" FOREIGN KEY ("CommunicationSenderID") REFERENCES __mj."CommunicationSender" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationSuppression_Preference" FOREIGN KEY ("CommunicationPreferenceID") REFERENCES __mj."CommunicationPreference" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationSuppression_BaseMessageType" FOREIGN KEY ("BaseMessageTypeID") REFERENCES __mj."CommunicationBaseMessageType" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationSuppression_RevokedByUser" FOREIGN KEY ("RevokedByUserID") REFERENCES __mj."User" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationSuppression_Log" FOREIGN KEY ("CommunicationLogID") REFERENCES __mj."CommunicationLog" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationSuppression_Policy" FOREIGN KEY ("CommunicationSuppressionPolicyID") REFERENCES __mj."CommunicationSuppressionPolicy" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationSuppression_CreatedByUser" FOREIGN KEY ("CreatedByUserID") REFERENCES __mj."User" (
    "ID"
  ),
  CONSTRAINT "CK_CommunicationSuppression_Target" CHECK (NOT "CommunicationEndpointID" IS NULL OR NOT "EntityID" IS NULL),
  CONSTRAINT "CK_CommunicationSuppression_PrincipalPair" CHECK ((
    "EntityID" IS NULL AND "RecordID" IS NULL
  )
  OR (
    NOT "EntityID" IS NULL AND NOT "RecordID" IS NULL
  )),
  CONSTRAINT "CK_CommunicationSuppression_Reason" CHECK ("Reason" IN (
    'User Unsubscribe',
    'Hard Bounce',
    'Spam Complaint',
    'Invalid Address',
    'Admin Block',
    'Policy'
  )),
  CONSTRAINT "CK_CommunicationSuppression_Source" CHECK ("Source" IN (
    'One-Click Header',
    'Preference Center',
    'Provider Webhook',
    'Admin',
    'API',
    'Policy',
    'Import'
  )),
  CONSTRAINT "CK_CommunicationSuppression_Status" CHECK ("Status" IN ('Active', 'Revoked', 'Expired')),
  CONSTRAINT "CK_CommunicationSuppression_Revocation" CHECK ((
    "Status" = 'Revoked' AND NOT "RevokedAt" IS NULL
  )
  OR (
    "Status" <> 'Revoked' AND "RevokedAt" IS NULL
  )),
  CONSTRAINT "CK_CommunicationSuppression_PolicyLink" CHECK ((
    "Reason" = 'Policy' AND NOT "CommunicationSuppressionPolicyID" IS NULL
  )
  OR (
    "Reason" <> 'Policy'
  ))
);

/* The gate's two hot lookups: by address, and by principal record. */
CREATE INDEX "IX_CommunicationSuppression_EndpointGate" ON __mj."CommunicationSuppression"("CommunicationEndpointID", "Status") INCLUDE ("CommunicationSenderID", "CommunicationPreferenceID", "BaseMessageTypeID", "Reason", "ExpiresAt");

CREATE INDEX "IX_CommunicationSuppression_PrincipalGate" ON __mj."CommunicationSuppression"("EntityID", "RecordID", "Status") INCLUDE ("CommunicationSenderID", "CommunicationPreferenceID", "BaseMessageTypeID", "Reason", "ExpiresAt");

/* At most one active Admin Block per address. Two admins blocking the same address at the same */
/* moment cannot both insert; the second gets a duplicate-key refusal and reports "already blocked". */
CREATE UNIQUE INDEX "UX_CommunicationSuppression_ActiveAdminBlock" ON __mj."CommunicationSuppression"("CommunicationEndpointID") NULLS NOT DISTINCT
WHERE
  "Reason" = 'Admin Block'
  AND "Status" = 'Active'
  AND NOT "CommunicationEndpointID" IS NULL;

/* =========================================================================== */
/* 7. CONSENT AUDIT (append-only) */
/* =========================================================================== */
CREATE TABLE __mj."CommunicationConsentAuditLog" (
  "ID" UUID NOT NULL DEFAULT GEN_RANDOM_UUID(),
  "CommunicationSuppressionID" UUID NULL,
  "CommunicationPrincipalPreferenceID" UUID NULL,
  "Action" VARCHAR(20) NOT NULL,
  "PreviousValue" TEXT NULL,
  "NewValue" TEXT NULL,
  "Source" VARCHAR(30) NOT NULL,
  "CommunicationLogID" UUID NULL,
  "IPAddress" VARCHAR(45) NULL,
  "UserAgent" VARCHAR(1000) NULL,
  "ChangedByUserID" UUID NULL,
  "ChangedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT "PK_CommunicationConsentAuditLog" PRIMARY KEY ("ID"),
  CONSTRAINT "FK_CommunicationConsentAuditLog_Suppression" FOREIGN KEY ("CommunicationSuppressionID") REFERENCES __mj."CommunicationSuppression" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationConsentAuditLog_PrincipalPreference" FOREIGN KEY ("CommunicationPrincipalPreferenceID") REFERENCES __mj."CommunicationPrincipalPreference" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationConsentAuditLog_Log" FOREIGN KEY ("CommunicationLogID") REFERENCES __mj."CommunicationLog" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationConsentAuditLog_ChangedByUser" FOREIGN KEY ("ChangedByUserID") REFERENCES __mj."User" (
    "ID"
  ),
  CONSTRAINT "CK_CommunicationConsentAuditLog_OneSubject" CHECK ((
    NOT "CommunicationSuppressionID" IS NULL
    AND "CommunicationPrincipalPreferenceID" IS NULL
  )
  OR (
    "CommunicationSuppressionID" IS NULL
    AND NOT "CommunicationPrincipalPreferenceID" IS NULL
  )),
  CONSTRAINT "CK_CommunicationConsentAuditLog_Action" CHECK ("Action" IN ('Created', 'Updated', 'Confirmed', 'Revoked', 'Expired')),
  CONSTRAINT "CK_CommunicationConsentAuditLog_Source" CHECK ("Source" IN (
    'One-Click Header',
    'Preference Center',
    'Signup Form',
    'Provider Webhook',
    'Admin',
    'API',
    'Policy',
    'Import',
    'System'
  ))
);

-- ===================== HAND-FINISHED (v6.3.0-edge.2 release build, addendum) =====================
-- trgCommunicationConsentAuditLog_AppendOnly. Reported needs-hand by the split converter.
-- SQL Server: an INSTEAD OF UPDATE, DELETE trigger that THROWs on any update, THROWs on a delete unless
-- SESSION_CONTEXT('MJ.CommsAuditErase') = 1, and otherwise performs the delete.
-- PostgreSQL has no INSTEAD OF triggers on tables, so this is the equivalent BEFORE UPDATE OR DELETE row
-- trigger: an UPDATE raises; a DELETE raises unless current_setting('mj.comms_audit_erase', true) = '1'
-- (spDeleteEntityWithCoreDependencies sets it transaction-locally around its audit delete), and
-- otherwise proceeds (RETURN OLD). Same messages; SQLSTATE P0001 in place of THROW 50101 / 50102.
-- It fires before the CodeGen __mj_UpdatedAt trigger alphabetically ("trgC…" < "trg_update_…" is not
-- guaranteed by name, so it does not rely on order: any UPDATE is refused whichever trigger runs first).
CREATE OR REPLACE FUNCTION __mj."fn_trgCommunicationConsentAuditLog_AppendOnly"()
RETURNS trigger
LANGUAGE plpgsql
AS $trg$
BEGIN
    IF TG_OP = 'UPDATE' THEN
        RAISE EXCEPTION 'Communication Consent Audit Log rows cannot be updated: the log is append-only.';
    END IF;
    IF COALESCE(current_setting('mj.comms_audit_erase', true), '') <> '1' THEN
        RAISE EXCEPTION 'Communication Consent Audit Log rows cannot be deleted: the log is append-only. Rows are removed only when their entity is deleted.';
    END IF;
    RETURN OLD;
END;
$trg$;

DROP TRIGGER IF EXISTS "trgCommunicationConsentAuditLog_AppendOnly" ON __mj."CommunicationConsentAuditLog";
CREATE TRIGGER "trgCommunicationConsentAuditLog_AppendOnly"
    BEFORE UPDATE OR DELETE ON __mj."CommunicationConsentAuditLog"
    FOR EACH ROW EXECUTE FUNCTION __mj."fn_trgCommunicationConsentAuditLog_AppendOnly"();
-- ===================== END HAND-FINISHED =====================


ALTER TABLE __mj."CommunicationLog"
  ADD COLUMN "EntityID" UUID NULL,
  ADD COLUMN "RecordID" VARCHAR(450) NULL,
  ADD COLUMN "CommunicationEndpointID" UUID NULL,
  ADD COLUMN "RecipientAddress" VARCHAR(320) NULL,
  ADD COLUMN "CommunicationSenderID" UUID NULL,
  ADD COLUMN "CommunicationPreferenceID" UUID NULL,
  ADD COLUMN "MessageClass" VARCHAR(20) NULL,
  ADD COLUMN "ScheduledAt" TIMESTAMPTZ NULL,
  ADD COLUMN "ProviderMessageID" VARCHAR(200) NULL,
  ADD COLUMN "UnsubscribeToken" UUID NULL,
  ADD COLUMN "TrackingToken" UUID NULL,
  ADD COLUMN "CorrelationData" TEXT NULL,
  ADD COLUMN "ComplianceDecision" TEXT NULL,
  ADD COLUMN "IsDryRun" BOOLEAN NOT NULL DEFAULT FALSE,
  ADD COLUMN "DeferredPayload" TEXT NULL,
  ADD CONSTRAINT "FK_CommunicationLog_Entity" FOREIGN KEY ("EntityID") REFERENCES __mj."Entity" (
    "ID"
  ),
  ADD CONSTRAINT "FK_CommunicationLog_Endpoint" FOREIGN KEY ("CommunicationEndpointID") REFERENCES __mj."CommunicationEndpoint" (
    "ID"
  ),
  ADD CONSTRAINT "FK_CommunicationLog_Sender" FOREIGN KEY ("CommunicationSenderID") REFERENCES __mj."CommunicationSender" (
    "ID"
  ),
  ADD CONSTRAINT "FK_CommunicationLog_Preference" FOREIGN KEY ("CommunicationPreferenceID") REFERENCES __mj."CommunicationPreference" (
    "ID"
  ),
  ADD CONSTRAINT "CK_CommunicationLog_MessageClass" CHECK ("MessageClass" IS NULL
  OR "MessageClass" IN ('Transactional', 'Operational', 'Marketing')),
  ADD CONSTRAINT "CK_CommunicationLog_PrincipalPair" CHECK ((
    "EntityID" IS NULL AND "RecordID" IS NULL
  )
  OR (
    NOT "EntityID" IS NULL AND NOT "RecordID" IS NULL
  ))
 /* =========================================================================== */ /* 8. COMMUNICATION LOG — new columns */ /* =========================================================================== */;

/* Non-enumerable capability token for one-click unsubscribe and preference center URLs. */
CREATE UNIQUE INDEX "UX_CommunicationLog_UnsubscribeToken" ON __mj."CommunicationLog"("UnsubscribeToken") NULLS NOT DISTINCT
WHERE
  NOT "UnsubscribeToken" IS NULL;

/* Separate capability token for open-tracking pixels so image-proxy logs never hold unsubscribe capability. */
CREATE UNIQUE INDEX "UX_CommunicationLog_TrackingToken" ON __mj."CommunicationLog"("TrackingToken") NULLS NOT DISTINCT
WHERE
  NOT "TrackingToken" IS NULL;

/* Webhook correlation fallback when custom args are missing. */
CREATE INDEX "IX_CommunicationLog_ProviderMessageID" ON __mj."CommunicationLog"("CommunicationProviderID", "ProviderMessageID")
WHERE
  NOT "ProviderMessageID" IS NULL;

/* Idempotency key for chunked/retried V2 runs: at most one log per (CommunicationRunID, CommunicationEndpointID). */
CREATE UNIQUE INDEX "UX_CommunicationLog_Run_Endpoint" ON __mj."CommunicationLog"("CommunicationRunID", "CommunicationEndpointID") NULLS NOT DISTINCT
WHERE
  NOT "CommunicationRunID" IS NULL AND NOT "CommunicationEndpointID" IS NULL;

/* Message history for one principal record. */
CREATE INDEX "IX_CommunicationLog_Principal" ON __mj."CommunicationLog"("EntityID", "RecordID", "MessageDate");

/* =========================================================================== */
/* 9. ACTIVITY (normalized delivery and engagement events) */
/* =========================================================================== */
CREATE TABLE __mj."CommunicationActivity" (
  "ID" UUID NOT NULL DEFAULT GEN_RANDOM_UUID(),
  "CommunicationLogID" UUID NULL,
  "CommunicationEndpointID" UUID NULL,
  "CommunicationSenderID" UUID NULL,
  "CommunicationProviderID" UUID NOT NULL,
  "EventType" VARCHAR(30) NOT NULL,
  "OccurredAt" TIMESTAMPTZ NOT NULL,
  "ReceivedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  "ProviderEventID" VARCHAR(200) NULL,
  "ProviderMessageID" VARCHAR(200) NULL,
  "TargetURL" VARCHAR(2000) NULL,
  "BounceCode" VARCHAR(50) NULL,
  "BounceReason" VARCHAR(1000) NULL,
  "IsMachineEvent" BOOLEAN NOT NULL DEFAULT FALSE,
  "IPAddress" VARCHAR(45) NULL,
  "UserAgent" VARCHAR(1000) NULL,
  "CorrelationData" TEXT NULL,
  "RawPayload" TEXT NULL,
  CONSTRAINT "PK_CommunicationActivity" PRIMARY KEY ("ID"),
  CONSTRAINT "FK_CommunicationActivity_Log" FOREIGN KEY ("CommunicationLogID") REFERENCES __mj."CommunicationLog" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationActivity_Endpoint" FOREIGN KEY ("CommunicationEndpointID") REFERENCES __mj."CommunicationEndpoint" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationActivity_Sender" FOREIGN KEY ("CommunicationSenderID") REFERENCES __mj."CommunicationSender" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationActivity_Provider" FOREIGN KEY ("CommunicationProviderID") REFERENCES __mj."CommunicationProvider" (
    "ID"
  ),
  CONSTRAINT "CK_CommunicationActivity_EventType" CHECK ("EventType" IN (
    'Queued',
    'Sent',
    'Delivered',
    'Deferred',
    'Dropped',
    'Soft Bounce',
    'Hard Bounce',
    'Opened',
    'Clicked',
    'Unsubscribed',
    'Spam Complaint'
  ))
);

/* At-least-once webhooks: one row per provider event. */
CREATE UNIQUE INDEX "UX_CommunicationActivity_ProviderEvent" ON __mj."CommunicationActivity"("CommunicationProviderID", "ProviderEventID") NULLS NOT DISTINCT
WHERE
  NOT "ProviderEventID" IS NULL;

/* Engagement and deliverability reporting per sender over time. */
CREATE INDEX "IX_CommunicationActivity_SenderTime" ON __mj."CommunicationActivity"("CommunicationSenderID", "EventType", "OccurredAt");

/* Retention purge of RawPayload / IP / user agent. */
CREATE INDEX "IX_CommunicationActivity_ReceivedAt" ON __mj."CommunicationActivity"("ReceivedAt");

/* =========================================================================== */
/* 10. COMPLIANCE REGIMES */
/* =========================================================================== */
CREATE TABLE __mj."CommunicationComplianceRegime" (
  "ID" UUID NOT NULL DEFAULT GEN_RANDOM_UUID(),
  "Name" VARCHAR(100) NOT NULL,
  "Description" TEXT NULL,
  "AppliesBy" VARCHAR(30) NOT NULL DEFAULT 'Recipient',
  "AppliesWhenJurisdictionUnknown" BOOLEAN NOT NULL DEFAULT TRUE,
  "ReferenceURL" VARCHAR(1000) NULL,
  "Status" VARCHAR(20) NOT NULL DEFAULT 'Disabled',
  CONSTRAINT "PK_CommunicationComplianceRegime" PRIMARY KEY ("ID"),
  CONSTRAINT "UQ_CommunicationComplianceRegime_Name" UNIQUE NULLS NOT DISTINCT (
    "Name"
  ),
  CONSTRAINT "CK_CommunicationComplianceRegime_AppliesBy" CHECK ("AppliesBy" IN ('Recipient', 'Sender', 'Recipient or Sender')),
  CONSTRAINT "CK_CommunicationComplianceRegime_Status" CHECK ("Status" IN ('Active', 'Disabled'))
);

CREATE TABLE __mj."CommunicationComplianceRuleType" (
  "ID" UUID NOT NULL DEFAULT GEN_RANDOM_UUID(),
  "Name" VARCHAR(100) NOT NULL,
  "Description" TEXT NULL,
  "DriverClass" VARCHAR(200) NOT NULL,
  "ParameterSchema" TEXT NULL,
  "Status" VARCHAR(20) NOT NULL DEFAULT 'Active',
  CONSTRAINT "PK_CommunicationComplianceRuleType" PRIMARY KEY ("ID"),
  CONSTRAINT "UQ_CommunicationComplianceRuleType_Name" UNIQUE NULLS NOT DISTINCT (
    "Name"
  ),
  CONSTRAINT "CK_CommunicationComplianceRuleType_Status" CHECK ("Status" IN ('Active', 'Disabled'))
);

CREATE TABLE __mj."CommunicationComplianceRegimeRule" (
  "ID" UUID NOT NULL DEFAULT GEN_RANDOM_UUID(),
  "CommunicationComplianceRegimeID" UUID NOT NULL,
  "CommunicationComplianceRuleTypeID" UUID NOT NULL,
  "BaseMessageTypeID" UUID NULL,
  "MessageClass" VARCHAR(20) NULL,
  "Parameters" TEXT NULL,
  "Notes" TEXT NULL,
  "Status" VARCHAR(20) NOT NULL DEFAULT 'Active',
  CONSTRAINT "PK_CommunicationComplianceRegimeRule" PRIMARY KEY ("ID"),
  CONSTRAINT "UQ_CommunicationComplianceRegimeRule_Scope" UNIQUE NULLS NOT DISTINCT (
    "CommunicationComplianceRegimeID",
    "CommunicationComplianceRuleTypeID",
    "BaseMessageTypeID",
    "MessageClass"
  ),
  CONSTRAINT "FK_CommunicationComplianceRegimeRule_Regime" FOREIGN KEY ("CommunicationComplianceRegimeID") REFERENCES __mj."CommunicationComplianceRegime" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationComplianceRegimeRule_RuleType" FOREIGN KEY ("CommunicationComplianceRuleTypeID") REFERENCES __mj."CommunicationComplianceRuleType" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationComplianceRegimeRule_BaseMessageType" FOREIGN KEY ("BaseMessageTypeID") REFERENCES __mj."CommunicationBaseMessageType" (
    "ID"
  ),
  CONSTRAINT "CK_CommunicationComplianceRegimeRule_MessageClass" CHECK ("MessageClass" IS NULL
  OR "MessageClass" IN ('Transactional', 'Operational', 'Marketing')),
  CONSTRAINT "CK_CommunicationComplianceRegimeRule_Status" CHECK ("Status" IN ('Active', 'Disabled'))
);

CREATE TABLE __mj."CommunicationComplianceRegimeJurisdiction" (
  "ID" UUID NOT NULL DEFAULT GEN_RANDOM_UUID(),
  "CommunicationComplianceRegimeID" UUID NOT NULL,
  "JurisdictionID" UUID NOT NULL,
  CONSTRAINT "PK_CommunicationComplianceRegimeJurisdiction" PRIMARY KEY ("ID"),
  CONSTRAINT "UQ_CommunicationComplianceRegimeJurisdiction_Pair" UNIQUE NULLS NOT DISTINCT (
    "CommunicationComplianceRegimeID",
    "JurisdictionID"
  ),
  CONSTRAINT "FK_CommunicationComplianceRegimeJurisdiction_Regime" FOREIGN KEY ("CommunicationComplianceRegimeID") REFERENCES __mj."CommunicationComplianceRegime" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationComplianceRegimeJurisdiction_Jurisdiction" FOREIGN KEY ("JurisdictionID") REFERENCES __mj."Jurisdiction" (
    "ID"
  )
);

/* =========================================================================== */
/* 11. WEBHOOK DEDUPLICATION & SENDING DOMAIN AUTHENTICATION */
/* =========================================================================== */
CREATE TABLE __mj."CommunicationProviderEvent" (
  "ID" UUID NOT NULL DEFAULT GEN_RANDOM_UUID(),
  "CommunicationProviderID" UUID NOT NULL,
  "ProviderEventID" VARCHAR(200) NOT NULL,
  "ReceivedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT "PK_CommunicationProviderEvent" PRIMARY KEY ("ID"),
  CONSTRAINT "UQ_CommunicationProviderEvent_Event" UNIQUE NULLS NOT DISTINCT (
    "CommunicationProviderID",
    "ProviderEventID"
  ),
  CONSTRAINT "FK_CommunicationProviderEvent_Provider" FOREIGN KEY ("CommunicationProviderID") REFERENCES __mj."CommunicationProvider" (
    "ID"
  )
);

CREATE INDEX "IX_CommunicationProviderEvent_ReceivedAt" ON __mj."CommunicationProviderEvent"("ReceivedAt");

ALTER TABLE __mj."CommunicationProvider"
  ADD COLUMN "RequireVerifiedDomain" BOOLEAN NOT NULL DEFAULT FALSE,
  ADD COLUMN "DeliveryGuarantee" VARCHAR(20) NOT NULL DEFAULT 'At Most Once',
  ADD CONSTRAINT "CK_CommunicationProvider_DeliveryGuarantee" CHECK ("DeliveryGuarantee" IN ('At Most Once', 'At Least Once'));

ALTER TABLE __mj."CommunicationRun"
  ADD COLUMN "ChunkCount" INT NULL,
  ADD COLUMN "DeliveryGuarantee" VARCHAR(20) NULL,
  ADD CONSTRAINT "CK_CommunicationRun_ChunkCount" CHECK ("ChunkCount" IS NULL OR "ChunkCount" > 0),
  ADD CONSTRAINT "CK_CommunicationRun_DeliveryGuarantee" CHECK ("DeliveryGuarantee" IS NULL
  OR "DeliveryGuarantee" IN ('At Most Once', 'At Least Once'));

CREATE TABLE __mj."CommunicationRunChunk" (
  "ID" UUID NOT NULL DEFAULT GEN_RANDOM_UUID(),
  "CommunicationRunID" UUID NOT NULL,
  "ChunkIndex" INT NOT NULL,
  "Status" VARCHAR(20) NOT NULL DEFAULT 'Complete',
  "RecipientCount" INT NOT NULL DEFAULT 0,
  "CompletedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  "ErrorMessage" TEXT NULL,
  CONSTRAINT "PK_CommunicationRunChunk" PRIMARY KEY ("ID"),
  CONSTRAINT "FK_CommunicationRunChunk_Run" FOREIGN KEY ("CommunicationRunID") REFERENCES __mj."CommunicationRun" (
    "ID"
  ),
  CONSTRAINT "UQ_CommunicationRunChunk_RunIndex" UNIQUE NULLS NOT DISTINCT (
    "CommunicationRunID",
    "ChunkIndex"
  ),
  CONSTRAINT "CK_CommunicationRunChunk_ChunkIndex" CHECK ("ChunkIndex" >= 0),
  CONSTRAINT "CK_CommunicationRunChunk_RecipientCount" CHECK ("RecipientCount" >= 0),
  CONSTRAINT "CK_CommunicationRunChunk_Status" CHECK ("Status" IN ('Complete', 'Failed'))
);

CREATE TABLE __mj."CommunicationSendingDomain" (
  "ID" UUID NOT NULL DEFAULT GEN_RANDOM_UUID(),
  "CommunicationProviderID" UUID NOT NULL,
  "CredentialID" UUID NULL,
  "Domain" VARCHAR(255) NOT NULL,
  "ProviderDomainID" VARCHAR(200) NULL,
  "Status" VARCHAR(20) NOT NULL DEFAULT 'Pending',
  "DNSRecords" TEXT NULL,
  "LastVerifiedAt" TIMESTAMPTZ NULL,
  "VerifiedAt" TIMESTAMPTZ NULL,
  CONSTRAINT "PK_CommunicationSendingDomain" PRIMARY KEY ("ID"),
  CONSTRAINT "UQ_CommunicationSendingDomain_Scope" UNIQUE NULLS NOT DISTINCT (
    "CommunicationProviderID",
    "CredentialID",
    "Domain"
  ),
  CONSTRAINT "FK_CommunicationSendingDomain_Provider" FOREIGN KEY ("CommunicationProviderID") REFERENCES __mj."CommunicationProvider" (
    "ID"
  ),
  CONSTRAINT "FK_CommunicationSendingDomain_Credential" FOREIGN KEY ("CredentialID") REFERENCES __mj."Credential" (
    "ID"
  ),
  CONSTRAINT "CK_CommunicationSendingDomain_Status" CHECK ("Status" IN ('Pending', 'Verified', 'Failed', 'Revoked'))
);

COMMENT ON TABLE __mj."Jurisdiction" IS 'A legal jurisdiction: a country (ISO 3166-1), a subdivision (ISO 3166-2, for example US-CA or CA-QC) or a named group such as EU or EEA. Generic core table; communications compliance is the first consumer.';

COMMENT ON COLUMN __mj."Jurisdiction"."Code" IS 'Unique code: ISO 3166-1 alpha-2 for countries (US, FR), ISO 3166-2 for subdivisions (US-CA), or a short group code (EU, EEA).';

COMMENT ON COLUMN __mj."Jurisdiction"."Name" IS 'Display name, for example France, California or European Union.';

COMMENT ON COLUMN __mj."Jurisdiction"."Description" IS 'Notes on the jurisdiction and what it covers.';

COMMENT ON COLUMN __mj."Jurisdiction"."Type" IS 'Country, Subdivision or Group. Groups contain other jurisdictions through Jurisdiction Members.';

COMMENT ON COLUMN __mj."Jurisdiction"."CountryID" IS 'For Country and Subdivision jurisdictions, the matching row in MJ: Countries.';

COMMENT ON COLUMN __mj."Jurisdiction"."Status" IS 'Active jurisdictions are used in resolution; Disabled ones are ignored.';

COMMENT ON TABLE __mj."JurisdictionMember" IS 'Containment between jurisdictions: EU contains FR, US contains US-CA. Groups can nest. Resolution expands a code to every jurisdiction that contains it.';

COMMENT ON COLUMN __mj."JurisdictionMember"."GroupJurisdictionID" IS 'The containing jurisdiction, for example EU or US.';

COMMENT ON COLUMN __mj."JurisdictionMember"."MemberJurisdictionID" IS 'The contained jurisdiction, for example FR or US-CA.';

COMMENT ON TABLE __mj."CommunicationPrincipal" IS 'Registers an entity whose records can receive communication (People, Organizations, Horseman, MJ Users). Nothing can be sent to a record of an entity that is not registered here, except transactional sends to a bare address.';

COMMENT ON COLUMN __mj."CommunicationPrincipal"."EntityID" IS 'The entity registered as a principal. One registration per entity.';

COMMENT ON COLUMN __mj."CommunicationPrincipal"."Name" IS 'Display name shown in the principal selector, for example People or Organizations. The selector is hidden when only one principal is active.';

COMMENT ON COLUMN __mj."CommunicationPrincipal"."Description" IS 'What this principal represents and which app registered it.';

COMMENT ON COLUMN __mj."CommunicationPrincipal"."DriverClass" IS 'ClassFactory key of a BaseCommunicationPrincipal subclass. NULL uses the metadata-only base class.';

COMMENT ON COLUMN __mj."CommunicationPrincipal"."Configuration" IS 'JSON slot mapping, for example {"Slots":{"FullName":"FullName","Jurisdiction":"Addresses.CountryISO2","Timezone":"Timezone","PreferredLanguage":"Language"}}. Slots may traverse relationships. Address slots live in Entity Communication Fields.';

COMMENT ON COLUMN __mj."CommunicationPrincipal"."DisplayOrder" IS 'Order of principals in pickers.';

COMMENT ON COLUMN __mj."CommunicationPrincipal"."Status" IS 'Active principals can be sent to; Disabled principals are refused by the engine.';

COMMENT ON COLUMN __mj."EntityCommunicationMessageType"."CommunicationPrincipalID" IS 'The principal this channel mapping belongs to. NULL for rows created before Communications V2; the engine falls back to matching EntityID.';

COMMENT ON TABLE __mj."CommunicationSenderType" IS 'Registers a kind of sender, usually backed by an entity, the way Communication Principal registers recipients. Default: Company over MJ: Companies. Multi-tenant apps can register tenants, newsletters, brands, and so on.';

COMMENT ON COLUMN __mj."CommunicationSenderType"."Name" IS 'Unique name, for example Company, Brand, Tenant or Newsletter.';

COMMENT ON COLUMN __mj."CommunicationSenderType"."Description" IS 'What this sender type represents.';

COMMENT ON COLUMN __mj."CommunicationSenderType"."EntityID" IS 'Entity whose records back senders of this type, for example MJ: Companies. NULL for senders defined only in Communication Senders (for example a brand with no source record).';

COMMENT ON COLUMN __mj."CommunicationSenderType"."DriverClass" IS 'ClassFactory key of a BaseCommunicationSender subclass for custom resolution, templating context or permission checks. NULL uses the metadata-only base class.';

COMMENT ON COLUMN __mj."CommunicationSenderType"."Configuration" IS 'JSON slot mapping from the backing entity, for example {"Slots":{"Name":"Name","SendingDomain":"Domain","LogoURL":"LogoURL","Website":"Website"}}. Values set on a Communication Sender row override mapped values.';

COMMENT ON COLUMN __mj."CommunicationSenderType"."Status" IS 'Active or Disabled.';

COMMENT ON TABLE __mj."CommunicationSender" IS 'A concrete sender: a company, brand, tenant or newsletter that communications go out on behalf of. Scopes suppression, preferences, permissions, templating and sending identity. Senders form a hierarchy through ParentSenderID; a block on a sender covers its descendants.';

COMMENT ON COLUMN __mj."CommunicationSender"."CommunicationSenderTypeID" IS 'The sender type this sender belongs to.';

COMMENT ON COLUMN __mj."CommunicationSender"."RecordID" IS 'Primary key of the backing record in the sender type''s entity (for example an MJ: Companies ID). NULL when the sender has no backing record.';

COMMENT ON COLUMN __mj."CommunicationSender"."ParentSenderID" IS 'Parent sender, for example the company a brand or newsletter belongs to. Suppressions, preferences and permissions on a parent apply to its descendants.';

COMMENT ON COLUMN __mj."CommunicationSender"."Name" IS 'Display name used in the preference center and reports.';

COMMENT ON COLUMN __mj."CommunicationSender"."Description" IS 'What this sender is and who manages it.';

COMMENT ON COLUMN __mj."CommunicationSender"."IsDefault" IS 'When 1, this sender is used for sends that name no sender. At most one default sender per instance.';

COMMENT ON COLUMN __mj."CommunicationSender"."FromEmail" IS 'Default From address for email sent by this sender.';

COMMENT ON COLUMN __mj."CommunicationSender"."FromName" IS 'Default From display name.';

COMMENT ON COLUMN __mj."CommunicationSender"."ReplyToEmail" IS 'Default Reply-To address.';

COMMENT ON COLUMN __mj."CommunicationSender"."FromPhone" IS 'Default sending phone number or short code for SMS, in E.164 form.';

COMMENT ON COLUMN __mj."CommunicationSender"."SendingDomain" IS 'Authenticated sending domain (SPF/DKIM/DMARC). Also a rate-limiting key for the send queue.';

COMMENT ON COLUMN __mj."CommunicationSender"."PostalAddress" IS 'Physical postal address injected into footers when a regime''s SenderIdentification rule requires it.';

COMMENT ON COLUMN __mj."CommunicationSender"."JurisdictionID" IS 'Where the sender is established. Regimes whose AppliesBy includes Sender apply based on this jurisdiction.';

COMMENT ON COLUMN __mj."CommunicationSender"."CommunicationProviderID" IS 'Default provider for this sender''s sends, overriding the instance default.';

COMMENT ON COLUMN __mj."CommunicationSender"."CredentialID" IS 'Provider credential for this sender (for example a per-tenant SendGrid subuser key). Secrets live only in MJ: Credentials.';

COMMENT ON COLUMN __mj."CommunicationSender"."PreferenceCenterURL" IS 'Public preference center URL for this sender. Used as the redirect after one-click unsubscribe and in footers.';

COMMENT ON COLUMN __mj."CommunicationSender"."TemplateContext" IS 'JSON brand variables exposed to templates and callers as Sender.*, for example {"LogoURL":"...","PrimaryColor":"#0B5394","FooterText":"..."}. Merged down the sender hierarchy: a child''s values override its parent''s.';

COMMENT ON COLUMN __mj."CommunicationSender"."Configuration" IS 'Driver-specific JSON settings for this sender.';

COMMENT ON COLUMN __mj."CommunicationSender"."EnforcementMode" IS 'Per-sender override of the instance compliance enforcement mode (Off, Shadow or Enforce). NULL uses the instance setting.';

COMMENT ON COLUMN __mj."CommunicationSender"."Status" IS 'Active senders can send; Suspended senders are paused (for example a reputation problem); Disabled senders are retired.';

COMMENT ON TABLE __mj."CommunicationSenderPermission" IS 'Who may view, send as, or manage a sender. Grants to a role or a single user, optionally inherited by child senders. Lets one instance host several companies or brands with separate teams.';

COMMENT ON COLUMN __mj."CommunicationSenderPermission"."CommunicationSenderID" IS 'The sender the grant applies to.';

COMMENT ON COLUMN __mj."CommunicationSenderPermission"."RoleID" IS 'Role granted the permission. Exactly one of RoleID and UserID is set.';

COMMENT ON COLUMN __mj."CommunicationSenderPermission"."UserID" IS 'User granted the permission. Exactly one of RoleID and UserID is set.';

COMMENT ON COLUMN __mj."CommunicationSenderPermission"."PermissionLevel" IS 'View: see activity and reports. Send: send as this sender. Manage: also edit the sender, its preferences and its suppressions. Each level includes the ones before it.';

COMMENT ON COLUMN __mj."CommunicationSenderPermission"."AppliesToChildSenders" IS 'When 1, the grant also applies to every descendant sender.';

COMMENT ON TABLE __mj."CommunicationEndpoint" IS 'One canonical address per channel (an email address, a phone number), shared by every principal that uses it. Holds deliverability health so a bounce protects every record sharing the address.';

COMMENT ON COLUMN __mj."CommunicationEndpoint"."BaseMessageTypeID" IS 'Channel of the address: the communication base message type (Email, SMS, ...).';

COMMENT ON COLUMN __mj."CommunicationEndpoint"."NormalizedValue" IS 'Normalized address: email lowercased and trimmed (dots and plus-tags kept); phone in E.164. NULL when Status is Erased.';

COMMENT ON COLUMN __mj."CommunicationEndpoint"."ValueHash" IS 'SHA-256 hex digest of the normalized value. Preserved on erasure so re-imported addresses resolve to the same suppressed endpoint.';

COMMENT ON COLUMN __mj."CommunicationEndpoint"."Domain" IS 'Email domain, for domain-level deliverability reporting. NULL for non-email channels.';

COMMENT ON COLUMN __mj."CommunicationEndpoint"."Status" IS 'Health summary maintained from activity. Suppression rows remain the authority for blocking.';

COMMENT ON COLUMN __mj."CommunicationEndpoint"."SoftBounceCount" IS 'Consecutive soft bounces since the last delivery. A configurable threshold converts repeated soft bounces into a suppression.';

COMMENT ON COLUMN __mj."CommunicationEndpoint"."LastSentAt" IS 'Last time any message was handed to a provider for this address.';

COMMENT ON COLUMN __mj."CommunicationEndpoint"."LastDeliveredAt" IS 'Last confirmed delivery.';

COMMENT ON COLUMN __mj."CommunicationEndpoint"."LastBouncedAt" IS 'Last bounce of any kind.';

COMMENT ON COLUMN __mj."CommunicationEndpoint"."LastEngagedAt" IS 'Last human open or click (machine events excluded).';

COMMENT ON TABLE __mj."CommunicationEndpointPrincipal" IS 'Which principal records have used which endpoint, maintained by the engine at send time. Lets an address-only signal (bounce, one-click unsubscribe) find every record it affects.';

COMMENT ON COLUMN __mj."CommunicationEndpointPrincipal"."CommunicationEndpointID" IS 'The endpoint.';

COMMENT ON COLUMN __mj."CommunicationEndpointPrincipal"."EntityID" IS 'Entity of the principal record.';

COMMENT ON COLUMN __mj."CommunicationEndpointPrincipal"."RecordID" IS 'Primary key of the principal record (polymorphic, paired with EntityID).';

COMMENT ON COLUMN __mj."CommunicationEndpointPrincipal"."FirstSeenAt" IS 'When the engine first resolved this record to this endpoint.';

COMMENT ON COLUMN __mj."CommunicationEndpointPrincipal"."LastSeenAt" IS 'When the engine last resolved this record to this endpoint.';

COMMENT ON TABLE __mj."CommunicationPreference" IS 'A preference people can opt into or out of, such as Weekly Newsletter or Event Reminders. Also the scope an unsubscribe writes. Can be shared across senders or owned by one.';

COMMENT ON COLUMN __mj."CommunicationPreference"."CommunicationSenderID" IS 'Owning sender. NULL means the preference is shared across senders; non-NULL means the preference is owned by that specific sender.';

COMMENT ON COLUMN __mj."CommunicationPreference"."Name" IS 'Name shown in the preference center. Unique per sender.';

COMMENT ON COLUMN __mj."CommunicationPreference"."Description" IS 'Explanation shown in the preference center.';

COMMENT ON COLUMN __mj."CommunicationPreference"."Category" IS 'Optional grouping heading in the preference center.';

COMMENT ON COLUMN __mj."CommunicationPreference"."MessageClass" IS 'Transactional, Operational or Marketing. Decides which suppression reasons and regime rules apply to messages sent under this preference.';

COMMENT ON COLUMN __mj."CommunicationPreference"."DefaultState" IS 'State assumed when a principal has no Principal Preference row. An applicable opt-in regime overrides Opted In for Marketing: explicit consent is then required.';

COMMENT ON COLUMN __mj."CommunicationPreference"."BaseMessageTypeID" IS 'Channel this preference applies to. NULL means all channels.';

COMMENT ON COLUMN __mj."CommunicationPreference"."IsUserVisible" IS 'When 0, the preference is internal and hidden from the preference center.';

COMMENT ON COLUMN __mj."CommunicationPreference"."DisplayOrder" IS 'Order in the preference center.';

COMMENT ON COLUMN __mj."CommunicationPreference"."Status" IS 'Active or Disabled. Sends naming a disabled preference are refused.';

COMMENT ON TABLE __mj."CommunicationPrincipalPreference" IS 'One principal record''s choice for one preference, with consent evidence. Each preference is either shared or owned by one sender; absence of a row means no explicit permission or denial.';

COMMENT ON COLUMN __mj."CommunicationPrincipalPreference"."EntityID" IS 'Entity of the principal record.';

COMMENT ON COLUMN __mj."CommunicationPrincipalPreference"."RecordID" IS 'Primary key of the principal record (polymorphic, paired with EntityID).';

COMMENT ON COLUMN __mj."CommunicationPrincipalPreference"."CommunicationPreferenceID" IS 'The preference this choice is for.';

COMMENT ON COLUMN __mj."CommunicationPrincipalPreference"."CommunicationSenderID" IS 'Sender this choice applies to (and its descendants). NULL means every sender.';

COMMENT ON COLUMN __mj."CommunicationPrincipalPreference"."State" IS 'Pending (awaiting double opt-in confirmation), Opted In or Opted Out.';

COMMENT ON COLUMN __mj."CommunicationPrincipalPreference"."OptInMethod" IS 'Whether consent was captured via Single or Double opt-in. Preserved after Pending transitions to Opted In.';

COMMENT ON COLUMN __mj."CommunicationPrincipalPreference"."ConfirmedAt" IS 'When double opt-in confirmation was completed. NULL for single opt-in or while still Pending.';

COMMENT ON COLUMN __mj."CommunicationPrincipalPreference"."ConfirmationToken" IS 'Random UUIDv4 token used in double opt-in confirmation links, separate from UnsubscribeToken.';

COMMENT ON COLUMN __mj."CommunicationPrincipalPreference"."ConsentSource" IS 'Where the choice was captured.';

COMMENT ON COLUMN __mj."CommunicationPrincipalPreference"."ConsentAt" IS 'When the choice was made.';

COMMENT ON COLUMN __mj."CommunicationPrincipalPreference"."ConsentText" IS 'The exact wording the person agreed to, kept as consent evidence where a regime requires it.';

COMMENT ON COLUMN __mj."CommunicationPrincipalPreference"."ExpiresAt" IS 'When implied consent lapses (for example under a ConsentExpiry rule). NULL means no expiry.';

COMMENT ON COLUMN __mj."CommunicationPrincipalPreference"."CommunicationLogID" IS 'Message whose link or header produced this choice, when applicable.';

COMMENT ON COLUMN __mj."CommunicationPrincipalPreference"."IPAddress" IS 'IP address of the request that made the choice.';

