CREATE OR REPLACE FUNCTION "__mj"."spCreateCommunicationActivity"(
    p_id UUID DEFAULT NULL,
    p_communicationlogid_clear boolean DEFAULT false,
    p_communicationlogid UUID DEFAULT NULL,
    p_communicationendpointid_clear boolean DEFAULT false,
    p_communicationendpointid UUID DEFAULT NULL,
    p_communicationsenderid_clear boolean DEFAULT false,
    p_communicationsenderid UUID DEFAULT NULL,
    p_communicationproviderid UUID DEFAULT NULL,
    p_eventtype varchar(30) DEFAULT NULL,
    p_occurredat TIMESTAMPTZ DEFAULT NULL,
    p_receivedat TIMESTAMPTZ DEFAULT NULL,
    p_providereventid_clear boolean DEFAULT false,
    p_providereventid varchar(200) DEFAULT NULL,
    p_providermessageid_clear boolean DEFAULT false,
    p_providermessageid varchar(200) DEFAULT NULL,
    p_targeturl_clear boolean DEFAULT false,
    p_targeturl varchar(2000) DEFAULT NULL,
    p_bouncecode_clear boolean DEFAULT false,
    p_bouncecode varchar(50) DEFAULT NULL,
    p_bouncereason_clear boolean DEFAULT false,
    p_bouncereason varchar(1000) DEFAULT NULL,
    p_ismachineevent BOOLEAN DEFAULT NULL,
    p_ipaddress_clear boolean DEFAULT false,
    p_ipaddress varchar(45) DEFAULT NULL,
    p_useragent_clear boolean DEFAULT false,
    p_useragent varchar(1000) DEFAULT NULL,
    p_correlationdata_clear boolean DEFAULT false,
    p_correlationdata TEXT DEFAULT NULL,
    p_rawpayload_clear boolean DEFAULT false,
    p_rawpayload TEXT DEFAULT NULL
) RETURNS SETOF "__mj"."vwCommunicationActivities" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."CommunicationActivity"
        (
            "ID",
            "CommunicationLogID",
                "CommunicationEndpointID",
                "CommunicationSenderID",
                "CommunicationProviderID",
                "EventType",
                "OccurredAt",
                "ReceivedAt",
                "ProviderEventID",
                "ProviderMessageID",
                "TargetURL",
                "BounceCode",
                "BounceReason",
                "IsMachineEvent",
                "IPAddress",
                "UserAgent",
                "CorrelationData",
                "RawPayload"
        )
    VALUES
        (
            v_new_id,
            CASE WHEN p_communicationlogid_clear = true THEN NULL ELSE COALESCE(p_communicationlogid, NULL) END,
                CASE WHEN p_communicationendpointid_clear = true THEN NULL ELSE COALESCE(p_communicationendpointid, NULL) END,
                CASE WHEN p_communicationsenderid_clear = true THEN NULL ELSE COALESCE(p_communicationsenderid, NULL) END,
                p_communicationproviderid,
                p_eventtype,
                p_occurredat,
                COALESCE(p_receivedat, NOW() AT TIME ZONE 'UTC'),
                CASE WHEN p_providereventid_clear = true THEN NULL ELSE COALESCE(p_providereventid, NULL) END,
                CASE WHEN p_providermessageid_clear = true THEN NULL ELSE COALESCE(p_providermessageid, NULL) END,
                CASE WHEN p_targeturl_clear = true THEN NULL ELSE COALESCE(p_targeturl, NULL) END,
                CASE WHEN p_bouncecode_clear = true THEN NULL ELSE COALESCE(p_bouncecode, NULL) END,
                CASE WHEN p_bouncereason_clear = true THEN NULL ELSE COALESCE(p_bouncereason, NULL) END,
                COALESCE(p_ismachineevent, FALSE),
                CASE WHEN p_ipaddress_clear = true THEN NULL ELSE COALESCE(p_ipaddress, NULL) END,
                CASE WHEN p_useragent_clear = true THEN NULL ELSE COALESCE(p_useragent, NULL) END,
                CASE WHEN p_correlationdata_clear = true THEN NULL ELSE COALESCE(p_correlationdata, NULL) END,
                CASE WHEN p_rawpayload_clear = true THEN NULL ELSE COALESCE(p_rawpayload, NULL) END
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj"."vwCommunicationActivities"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
