CREATE OR REPLACE FUNCTION "__mj"."spCreateCommunicationEndpoint"(
    p_id UUID DEFAULT NULL,
    p_basemessagetypeid UUID DEFAULT NULL,
    p_normalizedvalue_clear boolean DEFAULT false,
    p_normalizedvalue varchar(320) DEFAULT NULL,
    p_valuehash varchar(64) DEFAULT NULL,
    p_domain_clear boolean DEFAULT false,
    p_domain varchar(255) DEFAULT NULL,
    p_status varchar(20) DEFAULT NULL,
    p_softbouncecount int DEFAULT NULL,
    p_lastsentat_clear boolean DEFAULT false,
    p_lastsentat TIMESTAMPTZ DEFAULT NULL,
    p_lastdeliveredat_clear boolean DEFAULT false,
    p_lastdeliveredat TIMESTAMPTZ DEFAULT NULL,
    p_lastbouncedat_clear boolean DEFAULT false,
    p_lastbouncedat TIMESTAMPTZ DEFAULT NULL,
    p_lastengagedat_clear boolean DEFAULT false,
    p_lastengagedat TIMESTAMPTZ DEFAULT NULL
) RETURNS SETOF "__mj"."vwCommunicationEndpoints" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."CommunicationEndpoint"
        (
            "ID",
            "BaseMessageTypeID",
                "NormalizedValue",
                "ValueHash",
                "Domain",
                "Status",
                "SoftBounceCount",
                "LastSentAt",
                "LastDeliveredAt",
                "LastBouncedAt",
                "LastEngagedAt"
        )
    VALUES
        (
            v_new_id,
            p_basemessagetypeid,
                CASE WHEN p_normalizedvalue_clear = true THEN NULL ELSE COALESCE(p_normalizedvalue, NULL) END,
                p_valuehash,
                CASE WHEN p_domain_clear = true THEN NULL ELSE COALESCE(p_domain, NULL) END,
                COALESCE(p_status, 'Active'),
                COALESCE(p_softbouncecount, 0),
                CASE WHEN p_lastsentat_clear = true THEN NULL ELSE COALESCE(p_lastsentat, NULL) END,
                CASE WHEN p_lastdeliveredat_clear = true THEN NULL ELSE COALESCE(p_lastdeliveredat, NULL) END,
                CASE WHEN p_lastbouncedat_clear = true THEN NULL ELSE COALESCE(p_lastbouncedat, NULL) END,
                CASE WHEN p_lastengagedat_clear = true THEN NULL ELSE COALESCE(p_lastengagedat, NULL) END
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj"."vwCommunicationEndpoints"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
