    p_lastengagedat_clear boolean DEFAULT false,
    p_lastengagedat TIMESTAMPTZ DEFAULT NULL
) RETURNS SETOF "__mj"."vwCommunicationEndpoints" AS $$
DECLARE
    v_updated_count INTEGER;
BEGIN
    UPDATE "__mj"."CommunicationEndpoint"
    SET
        "BaseMessageTypeID" = COALESCE(p_basemessagetypeid, "BaseMessageTypeID"),
        "NormalizedValue" = CASE WHEN p_normalizedvalue_clear = true THEN NULL ELSE COALESCE(p_normalizedvalue, "NormalizedValue") END,
        "ValueHash" = COALESCE(p_valuehash, "ValueHash"),
        "Domain" = CASE WHEN p_domain_clear = true THEN NULL ELSE COALESCE(p_domain, "Domain") END,
        "Status" = COALESCE(p_status, "Status"),
        "SoftBounceCount" = COALESCE(p_softbouncecount, "SoftBounceCount"),
        "LastSentAt" = CASE WHEN p_lastsentat_clear = true THEN NULL ELSE COALESCE(p_lastsentat, "LastSentAt") END,
        "LastDeliveredAt" = CASE WHEN p_lastdeliveredat_clear = true THEN NULL ELSE COALESCE(p_lastdeliveredat, "LastDeliveredAt") END,
        "LastBouncedAt" = CASE WHEN p_lastbouncedat_clear = true THEN NULL ELSE COALESCE(p_lastbouncedat, "LastBouncedAt") END,
        "LastEngagedAt" = CASE WHEN p_lastengagedat_clear = true THEN NULL ELSE COALESCE(p_lastengagedat, "LastEngagedAt") END,
        "__mj_UpdatedAt" = (NOW() AT TIME ZONE 'UTC')
    WHERE
        "ID" = p_id;

    GET DIAGNOSTICS v_updated_count = ROW_COUNT;

    IF v_updated_count = 0 THEN
        -- Nothing was updated, return empty result set
        RETURN;
