CREATE OR REPLACE FUNCTION "__mj"."spCreateCommunicationPreference"(
    p_id UUID DEFAULT NULL,
    p_communicationsenderid_clear boolean DEFAULT false,
    p_communicationsenderid UUID DEFAULT NULL,
    p_name varchar(200) DEFAULT NULL,
    p_description_clear boolean DEFAULT false,
    p_description TEXT DEFAULT NULL,
    p_category_clear boolean DEFAULT false,
    p_category varchar(100) DEFAULT NULL,
    p_messageclass varchar(20) DEFAULT NULL,
    p_defaultstate varchar(20) DEFAULT NULL,
    p_basemessagetypeid_clear boolean DEFAULT false,
    p_basemessagetypeid UUID DEFAULT NULL,
    p_isuservisible BOOLEAN DEFAULT NULL,
    p_displayorder int DEFAULT NULL,
    p_status varchar(20) DEFAULT NULL
) RETURNS SETOF "__mj"."vwCommunicationPreferences" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."CommunicationPreference"
        (
            "ID",
            "CommunicationSenderID",
                "Name",
                "Description",
                "Category",
                "MessageClass",
                "DefaultState",
                "BaseMessageTypeID",
                "IsUserVisible",
                "DisplayOrder",
                "Status"
        )
    VALUES
        (
            v_new_id,
            CASE WHEN p_communicationsenderid_clear = true THEN NULL ELSE COALESCE(p_communicationsenderid, NULL) END,
                p_name,
                CASE WHEN p_description_clear = true THEN NULL ELSE COALESCE(p_description, NULL) END,
                CASE WHEN p_category_clear = true THEN NULL ELSE COALESCE(p_category, NULL) END,
                COALESCE(p_messageclass, 'Marketing'),
                COALESCE(p_defaultstate, 'Opted In'),
                CASE WHEN p_basemessagetypeid_clear = true THEN NULL ELSE COALESCE(p_basemessagetypeid, NULL) END,
                COALESCE(p_isuservisible, TRUE),
                COALESCE(p_displayorder, 0),
                COALESCE(p_status, 'Active')
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj"."vwCommunicationPreferences"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
