    SET
        "CommunicationSenderID" = CASE WHEN p_communicationsenderid_clear = true THEN NULL ELSE COALESCE(p_communicationsenderid, "CommunicationSenderID") END,
        "Name" = COALESCE(p_name, "Name"),
        "Description" = CASE WHEN p_description_clear = true THEN NULL ELSE COALESCE(p_description, "Description") END,
        "Category" = CASE WHEN p_category_clear = true THEN NULL ELSE COALESCE(p_category, "Category") END,
        "MessageClass" = COALESCE(p_messageclass, "MessageClass"),
        "DefaultState" = COALESCE(p_defaultstate, "DefaultState"),
        "BaseMessageTypeID" = CASE WHEN p_basemessagetypeid_clear = true THEN NULL ELSE COALESCE(p_basemessagetypeid, "BaseMessageTypeID") END,
        "IsUserVisible" = COALESCE(p_isuservisible, "IsUserVisible"),
        "DisplayOrder" = COALESCE(p_displayorder, "DisplayOrder"),
        "Status" = COALESCE(p_status, "Status"),
        "__mj_UpdatedAt" = (NOW() AT TIME ZONE 'UTC')
