                COALESCE(p_deliveryguarantee, 'At Most Once')
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj"."vwCommunicationProviders"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
