CREATE OR REPLACE FUNCTION "__mj"."spCreateCommunicationRunChunk"(
    p_id UUID DEFAULT NULL,
    p_communicationrunid UUID DEFAULT NULL,
    p_chunkindex int DEFAULT NULL,
    p_status varchar(20) DEFAULT NULL,
    p_recipientcount int DEFAULT NULL,
    p_completedat TIMESTAMPTZ DEFAULT NULL,
    p_errormessage_clear boolean DEFAULT false,
    p_errormessage TEXT DEFAULT NULL
) RETURNS SETOF "__mj"."vwCommunicationRunChunks" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."CommunicationRunChunk"
        (
            "ID",
            "CommunicationRunID",
                "ChunkIndex",
                "Status",
                "RecipientCount",
                "CompletedAt",
                "ErrorMessage"
        )
    VALUES
        (
            v_new_id,
            p_communicationrunid,
                p_chunkindex,
                COALESCE(p_status, 'Complete'),
                COALESCE(p_recipientcount, 0),
                COALESCE(p_completedat, NOW() AT TIME ZONE 'UTC'),
                CASE WHEN p_errormessage_clear = true THEN NULL ELSE COALESCE(p_errormessage, NULL) END
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj"."vwCommunicationRunChunks"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
