CREATE OR REPLACE FUNCTION "__mj"."spCreateCommunicationRun"(
    p_id UUID DEFAULT NULL,
    p_userid UUID DEFAULT NULL,
    p_direction varchar(20) DEFAULT NULL,
    p_status varchar(20) DEFAULT NULL,
    p_startedat_clear boolean DEFAULT false,
    p_startedat TIMESTAMPTZ DEFAULT NULL,
    p_endedat_clear boolean DEFAULT false,
    p_endedat TIMESTAMPTZ DEFAULT NULL,
    p_comments_clear boolean DEFAULT false,
    p_comments TEXT DEFAULT NULL,
    p_errormessage_clear boolean DEFAULT false,
    p_errormessage TEXT DEFAULT NULL,
    p_chunkcount_clear boolean DEFAULT false,
    p_chunkcount int DEFAULT NULL,
    p_deliveryguarantee_clear boolean DEFAULT false,
    p_deliveryguarantee varchar(20) DEFAULT NULL
) RETURNS SETOF "__mj"."vwCommunicationRuns" AS $$
DECLARE
    v_new_id UUID;
BEGIN
    v_new_id := COALESCE(p_id, gen_random_uuid());
    INSERT INTO "__mj"."CommunicationRun"
        (
            "ID",
            "UserID",
                "Direction",
                "Status",
                "StartedAt",
                "EndedAt",
                "Comments",
                "ErrorMessage",
                "ChunkCount",
                "DeliveryGuarantee"
        )
    VALUES
        (
            v_new_id,
            p_userid,
                p_direction,
                p_status,
                CASE WHEN p_startedat_clear = true THEN NULL ELSE COALESCE(p_startedat, NULL) END,
                CASE WHEN p_endedat_clear = true THEN NULL ELSE COALESCE(p_endedat, NULL) END,
                CASE WHEN p_comments_clear = true THEN NULL ELSE COALESCE(p_comments, NULL) END,
                CASE WHEN p_errormessage_clear = true THEN NULL ELSE COALESCE(p_errormessage, NULL) END,
                CASE WHEN p_chunkcount_clear = true THEN NULL ELSE COALESCE(p_chunkcount, NULL) END,
                CASE WHEN p_deliveryguarantee_clear = true THEN NULL ELSE COALESCE(p_deliveryguarantee, NULL) END
        )
    ;

    RETURN QUERY
    SELECT * FROM "__mj"."vwCommunicationRuns"
    WHERE "ID" = v_new_id;
END;
$$ LANGUAGE plpgsql;
