CREATE OR REPLACE FUNCTION "__mj"."spUpdateCommunicationRun"(
    p_id UUID,
    p_userid UUID DEFAULT NULL,
    p_direction varchar(20) DEFAULT NULL,
    p_status varchar(20) DEFAULT NULL,
    p_startedat_clear boolean DEFAULT false,
    p_startedat TIMESTAMPTZ DEFAULT NULL,
    p_endedat_clear boolean DEFAULT false,
    p_endedat TIMESTAMPTZ DEFAULT NULL,
    p_comments_clear boolean DEFAULT false,
    p_comments TEXT DEFAULT NULL,
    p_errormessage_clear boolean DEFAULT false,
    p_errormessage TEXT DEFAULT NULL,
    p_chunkcount_clear boolean DEFAULT false,
    p_chunkcount int DEFAULT NULL,
    p_deliveryguarantee_clear boolean DEFAULT false,
    p_deliveryguarantee varchar(20) DEFAULT NULL
) RETURNS SETOF "__mj"."vwCommunicationRuns" AS $$
DECLARE
    v_updated_count INTEGER;
BEGIN
    UPDATE "__mj"."CommunicationRun"
    SET
        "UserID" = COALESCE(p_userid, "UserID"),
        "Direction" = COALESCE(p_direction, "Direction"),
        "Status" = COALESCE(p_status, "Status"),
        "StartedAt" = CASE WHEN p_startedat_clear = true THEN NULL ELSE COALESCE(p_startedat, "StartedAt") END,
        "EndedAt" = CASE WHEN p_endedat_clear = true THEN NULL ELSE COALESCE(p_endedat, "EndedAt") END,
        "Comments" = CASE WHEN p_comments_clear = true THEN NULL ELSE COALESCE(p_comments, "Comments") END,
        "ErrorMessage" = CASE WHEN p_errormessage_clear = true THEN NULL ELSE COALESCE(p_errormessage, "ErrorMessage") END,
        "ChunkCount" = CASE WHEN p_chunkcount_clear = true THEN NULL ELSE COALESCE(p_chunkcount, "ChunkCount") END,
        "DeliveryGuarantee" = CASE WHEN p_deliveryguarantee_clear = true THEN NULL ELSE COALESCE(p_deliveryguarantee, "DeliveryGuarantee") END,
        "__mj_UpdatedAt" = (NOW() AT TIME ZONE 'UTC')
    WHERE
        "ID" = p_id;

    GET DIAGNOSTICS v_updated_count = ROW_COUNT;

    IF v_updated_count = 0 THEN
        -- Nothing was updated, return empty result set
        RETURN;
    END IF;

    -- Return the updated record from the base view
    RETURN QUERY
    SELECT * FROM "__mj"."vwCommunicationRuns"
    WHERE "ID" = p_id;
END;
$$ LANGUAGE plpgsql;
