    p_credentialid_clear boolean DEFAULT false,
    p_credentialid UUID DEFAULT NULL,
    p_domain varchar(255) DEFAULT NULL,
    p_providerdomainid_clear boolean DEFAULT false,
    p_providerdomainid varchar(200) DEFAULT NULL,
    p_status varchar(20) DEFAULT NULL,
    p_dnsrecords_clear boolean DEFAULT false,
