                "CredentialID",
                "Domain",
                "ProviderDomainID",
                "Status",
                "DNSRecords",
                "LastVerifiedAt",
                "VerifiedAt"
        )
    VALUES
        (
            v_new_id,
            p_communicationproviderid,
                CASE WHEN p_credentialid_clear = true THEN NULL ELSE COALESCE(p_credentialid, NULL) END,
                p_domain,
                CASE WHEN p_providerdomainid_clear = true THEN NULL ELSE COALESCE(p_providerdomainid, NULL) END,
                COALESCE(p_status, 'Pending'),
                CASE WHEN p_dnsrecords_clear = true THEN NULL ELSE COALESCE(p_dnsrecords, NULL) END,
                CASE WHEN p_lastverifiedat_clear = true THEN NULL ELSE COALESCE(p_lastverifiedat, NULL) END,
                CASE WHEN p_verifiedat_clear = true THEN NULL ELSE COALESCE(p_verifiedat, NULL) END
