            v_new_id,
            p_entityid,
                p_basemessagetypeid,
                COALESCE(p_isactive, TRUE),
                CASE WHEN p_communicationprincipalid_clear = true THEN NULL ELSE COALESCE(p_communicationprincipalid, NULL) END
